def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings - more careful approach."""
    # First, let's see if we're dealing with insertions/deletions or substitutions
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    first_diff_pos = None
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            first_diff_pos = i
            break

    # If no difference found in common part, check length
    if first_diff_pos is None:
        if len(s_in) != len(s_out):
            # One string is longer - insertion/deletion
            first_diff_pos = min_len
        else:
            return None, None, None  # Identical strings

    # Check if this is a simple substitution
    if len(s_in) == len(s_out):
        return s_in[first_diff_pos], s_out[first_diff_pos], first_diff_pos
    elif len(s_in) > len(s_out):
        # Deletion - character removed
        return s_in[first_diff_pos], "", first_diff_pos
    else:
        # Insertion - character added  
        return "", s_out[first_diff_pos], first_diff_pos

inputs = ['kijx', 'badz', 'ujejf', 'abizx', 'kvibhx']
outputs = ['kzejx', 'badz', 'ujejf', 'abzezx', 'kjfabhx']

changed = [(0, 'kijx', 'kzejx'), (3, 'abizx', 'abzezx'), (4, 'kvibhx', 'kjfabhx')]

print("Analyzing each changed pair:")
for idx, s_in, s_out in changed:
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
    print(f"Pair {idx}: '{s_in}' -> '{s_out}'")
    print(f"  First difference at position {pos}: '{old_sub}' -> '{new_sub}'")

    # Let's see what the actual transformation looks like
    if pos < len(s_in) and pos < len(s_out):
        if old_sub == new_sub:
            print(f"  Same character at position {pos}")
        else:
            print(f"  Replace '{old_sub}' with '{new_sub}' at position {pos}")
    elif pos >= len(s_in) and len(s_out) > len(s_in):
        print(f"  Insert '{new_sub}' at position {pos} (end)")
    elif pos >= len(s_out) and len(s_in) > len(s_out):
        print(f"  Delete character at position {pos} (end)")
    print()

